    \u0275\u0275elementStart(17, "h2");
    \u0275\u0275text(18, "4. Data Transfers");
    \u0275\u0275elementEnd();
    \u0275\u0275elementStart(19, "p");
    \u0275\u0275text(20, "Your data may be processed in countries outside your own. We use standard contractual clauses to ensure adequate protection for international transfers.");
    \u0275\u0275elementEnd();
    \u0275\u0275elementStart(21, "h2");
    \u0275\u0275text(22, "5. Cookies and Tracking");
    \u0275\u0275elementEnd();
    \u0275\u0275elementStart(23, "p");
    \u0275\u0275text(24, "Woven uses only essential session cookies required for authentication. We do not use advertising cookies or cross-site tracking.");
    \u0275\u0275elementEnd();
    \u0275\u0275elementStart(25, "h2");
    \u0275\u0275text(26, "6. Data Breach Notification");
